//! Tier 3: Cross-validate against JEOD SIM_dyncomp RUN_2 trajectory.
//!
//! This test reads the CSV reference trajectory generated by JEOD's Trick
//! simulation and compares key properties against our propagation.
//!
//! RUN_2 uses:
//! - Spherical gravity (Earth only, no Sun/Moon)
//! - Atmosphere model ON but aero drag OFF
//! - ISS mass configuration
//! - 28800s (8 hours), logged every 60s
//!
//! Since JEOD's "spherical" gravity is still point-mass GM/r² (degree 0),
//! our point-mass propagation from the same initial conditions should track
//! closely. Differences come from: JEOD includes atmosphere state (but no
//! drag force), and JEOD integrates rotational state (we don't yet).

use glam::DVec3;
use jeod_dynamics::{rk4_translational_step, TranslationalState};
use jeod_test_data::crossval::{CrossvalReport, StateLog};
use jeod_test_data::dyncomp_csv::load_dyncomp_csv;
use std::path::Path;

const MU_EARTH: f64 = 3.986_004_415e14;

fn point_mass_accel(pos: DVec3) -> DVec3 {
    let r_sq = pos.length_squared();
    let r_mag = r_sq.sqrt();
    pos * (-MU_EARTH / (r_sq * r_mag))
}

#[test]
fn tier3_cross_validate_against_jeod_dyncomp() {
    let csv_path =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../../test_data/dyncomp_run2_state.csv");

    assert!(
        csv_path.exists(),
        "JEOD reference trajectory not found at {}. \
         Generate with: docker run --rm -v $(pwd)/test_data:/output jeod-trick",
        csv_path.display()
    );

    let jeod_trajectory = load_dyncomp_csv(&csv_path);
    assert!(
        jeod_trajectory.len() > 100,
        "Expected more than 100 records, got {}",
        jeod_trajectory.len()
    );

    // Use JEOD's initial state
    let initial = &jeod_trajectory[0];
    let mut state = TranslationalState {
        position: initial.composite_body.position,
        velocity: initial.composite_body.velocity,
    };

    println!("Tier 3: JEOD SIM_dyncomp RUN_2 cross-validation");
    println!(
        "  Initial position: [{:.2}, {:.2}, {:.2}] m",
        initial.composite_body.position.x,
        initial.composite_body.position.y,
        initial.composite_body.position.z
    );
    println!(
        "  JEOD trajectory: {} points over {:.0}s",
        jeod_trajectory.len(),
        jeod_trajectory.last().unwrap().time
    );
    println!();

    let dt = 0.03125; // match JEOD's SIM_dyncomp integration rate (32 Hz)
    let mut current_time = 0.0_f64;

    let mut our_states = Vec::with_capacity(jeod_trajectory.len() - 1);
    let ref_states: Vec<StateLog> = jeod_trajectory[1..]
        .iter()
        .map(|r| StateLog {
            time: r.time,
            position: Some(r.composite_body.position),
            velocity: Some(r.composite_body.velocity),
            acceleration: r.derivs.as_ref().map(|d| d.trans_accel),
            ang_accel: r.derivs.as_ref().map(|d| d.rot_accel),
            ..Default::default()
        })
        .collect();

    for jeod_record in &jeod_trajectory[1..] {
        // Propagate our state to match JEOD's timestamp
        while current_time + dt <= jeod_record.time + 0.001 {
            state = rk4_translational_step(&state, |s| point_mass_accel(s.position), dt);
            current_time += dt;
        }
        // Handle any fractional remainder
        let remainder = jeod_record.time - current_time;
        if remainder > 0.01 {
            state = rk4_translational_step(&state, |s| point_mass_accel(s.position), remainder);
            current_time += remainder;
        }

        our_states.push(StateLog {
            time: jeod_record.time,
            position: Some(state.position),
            velocity: Some(state.velocity),
            ..Default::default()
        });

        let pos_error = (state.position - jeod_record.composite_body.position).length();
        let vel_error = (state.velocity - jeod_record.composite_body.velocity).length();

        // Log progress at key points
        if (jeod_record.time % 3600.0).abs() < 30.1 {
            println!(
                "  t={:6.0}s ({:.1}h): pos_err={:10.1}m  vel_err={:.4}m/s  r={:.1}km",
                jeod_record.time,
                jeod_record.time / 3600.0,
                pos_error,
                vel_error,
                state.position.length() / 1000.0,
            );
        }
    }

    let mut report = CrossvalReport::compute(
        "tier3_cross_validate_against_jeod_dyncomp",
        &our_states,
        &ref_states,
    );
    report.position_tol = Some([0.5; 3]);
    report.velocity_tol = Some([0.001; 3]);
    report.write();

    let max_pos_error = report.max_position_error();
    let max_vel_error = report.max_velocity_error();

    println!();
    println!("  Max position error: {:.6e} m", max_pos_error);
    println!("  Max velocity error: {:.6e} m/s", max_vel_error);

    // dt=0.03125s matches JEOD's SIM_dyncomp integration rate (32 Hz).
    // With point-mass gravity and matching timestep, the only residual comes
    // from floating-point differences in the RK4 implementation.
    assert!(
        max_pos_error < 0.5,
        "Position error {:.2}m exceeds 0.5m over 8 hours",
        max_pos_error
    );
    assert!(
        max_vel_error < 0.001,
        "Velocity error {:.6}m/s exceeds 0.001 m/s over 8 hours",
        max_vel_error
    );
}
